/// Every initializer form TypeScript folds to a number or a string, with the value the checker gives it (the model test
/// in `crates/semantic/tests/enum_member_values.rs` asks the checker for each).
#[test]
fn an_enum_member_the_structural_lane_can_fold_has_the_value_typescript_gives_it() {
    let numbers: [(&str, f64); 24] = [
        ("1", 1.0),
        ("-1", -1.0),
        ("+1", 1.0),
        ("~1", -2.0),
        ("(2)", 2.0),
        ("0x10", 16.0),
        ("1e3", 1000.0),
        ("1_000", 1000.0),
        ("1 << 2", 4.0),
        ("-8 >> 1", -4.0),
        ("-8 >>> 28", 15.0),
        ("6 & 3", 2.0),
        ("6 | 1", 7.0),
        ("6 ^ 3", 5.0),
        ("2 ** 3", 8.0),
        ("7 % 4", 3.0),
        ("7 / 2", 3.5),
        ("1 + 2 * 3", 7.0),
        ("-(1 + 2)", -3.0),
        ("(1 + 2) * 3", 9.0),
        ("5 - 2 - 1", 2.0),
        ("0", 0.0),
        ("-0", 0.0),
        ("1 << 31", -2147483648.0),
    ];
    for (init, value) in numbers {
        let (ty, diagnostics) = member_of(init);
        assert_eq!(ty, member(json!({ "kind": "numberLiteral", "value": value })), "{init}");
        assert_eq!(diagnostics, Vec::<String>::new(), "{init}");
    }
    let strings = [("\\"a\\"", "a"), ("'a'", "a"), ("`t`", "t"), ("\\"a\\" + \\"b\\"", "ab"), ("\\"a\\" + 1", "a1"), ("1 + \\"a\\"", "1a")];
    for (init, value) in strings {
        let (ty, diagnostics) = member_of(init);
        assert_eq!(ty, member(json!({ "kind": "stringLiteral", "value": value })), "{init}");
        assert_eq!(diagnostics, Vec::<String>::new(), "{init}");
    }
}

/// A value the structural lane cannot fold is not known: the member is never its own name, the type stays unresolved
/// and says so, and the checker lane gives the value.
#[test]
fn an_enum_member_with_a_value_the_structural_lane_cannot_fold_stays_unresolved() {
    let unresolved = json!({ "kind": "named", "name": "E.A", "args": [] });
    for init in [
        "compute()",
        "OTHER",
        "true",
        "1 / 0",
        "0 / 0",
        "2 ** 1024",
        "\\"a\\" + 1.5",
        "\\"a\\" + OTHER",
        "`t${1}`",
        "1 < 2",
        "!1",
        "typeof 1",
        "void 0",
        "B",
        "E.B",
    ] {
        let (ty, diagnostics) = member_of(init);
        assert_eq!(ty, unresolved, "{init}");
        assert_eq!(diagnostics.len(), 1, "{init}: {diagnostics:?}");
        assert!(diagnostics[0].starts_with("Cannot resolve type 'E.A'"), "{init}: {diagnostics:?}");
    }
}

#[test]
fn a_member_that_reads_an_earlier_member_of_its_enum_has_its_value() {
    let source = r#"
        enum E { A = 1, B = A | 2, C = E.B + 1, D = E["C"] << 1, F = "x", G = F + "y" }
        export function C(props: { b: E.B; c: E.C; d: E.D; g: E.G }) { return <b />; }
    "#;
    let (props, diagnostics) = props_of(&[("case.tsx", source)]);
    let number = |member: &str, value: f64| {
