/// Numbering counts up from the last known value; after a value that is not known, no later member has one.
#[test]
fn auto_increment_follows_only_known_values() {
    let source = r#"
        declare const compute: () => number;
        enum E { Shift = 1 << 2, Next, Plain = 3, After, Fn = compute(), AfterFn, Str = "s", AfterStr }
        export function C(props: { next: E.Next; after: E.After; afterFn: E.AfterFn; afterStr: E.AfterStr; fnMember: E.Fn }) { return <b />; }
    "#;
    let (props, _) = props_of(&[("case.tsx", source)]);
    let number = |member: &str, value: f64| {
        json!({ "kind": "enumMember", "enum": "E", "member": member, "value": { "kind": "numberLiteral", "value": value } })
    };
    assert_eq!(props["next"], number("Next", 5.0));
    assert_eq!(props["after"], number("After", 4.0));
    for name in ["afterFn", "afterStr", "fnMember"] {
